v.fn(f, { color: H.colors.accent, width: 3 });
v.line(p, -8, p, 8, { color: H.colors.warn, width: 1.5, dash: [5, 5] });
v.line(-8, q, 8, q, { color: H.colors.good, width: 1.5, dash: [5, 5] });
const X = 7.5, Y = 7.5, ak = Math.max(0.5, Math.abs(k));
const roomUp = Y - q, roomDown = q + Y;
const room = (k >= 0 ? roomUp : roomDown);
let dMin = Math.max(0.5, ak / Math.max(0.8, room - 0.3));
let dMax = Math.max(dMin + 0.2, Math.min(X - p, 5));
let xs;
if (p + dMin > X) {
  const room2 = (k >= 0 ? roomDown : roomUp);
  let dl = Math.max(0.5, ak / Math.max(0.8, room2 - 0.3));
  let dr = Math.max(dl + 0.2, Math.min(p + X, 5));
  const c = (dl + dr) / 2, amp = (dr - dl) / 2;
  xs = p - (c + amp * Math.sin(t * 0.8));
} else {
  const c = (dMin + dMax) / 2, amp = (dMax - dMin) / 2;
  xs = p + (c + amp * Math.sin(t * 0.8));
}
const yd = f(xs);
v.dot(xs, yd, { r: 6, fill: H.colors.violet });
v.text("(" + xs.toFixed(1) + ", " + yd.toFixed(1) + ")", xs + 0.2, yd + 0.5, { color: H.colors.violet, size: 12 });
